import{_ as e}from"./chunks/architecture.Cs8uKTTN.js";import{_ as a,o as r,c as o,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"swag2mcp","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1784892466000}'),s={name:"index.md"};function i(d,t,c,p,l,h){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="swag2mcp" tabindex="-1">swag2mcp <a class="header-anchor" href="#swag2mcp" aria-label="Permalink to &quot;swag2mcp&quot;">​</a></h1><div style="background:#dc2626;color:white;padding:20px 24px;border-radius:12px;text-align:center;font-size:1.4em;font-weight:700;margin:24px 0;"> 🚧 WORK IN PROGRESS — release coming soon! </div><p>Bridges OpenAPI/Swagger/Postman API specifications with LLM agents via the Model Context Protocol (MCP).</p><a href="https://www.youtube.com/watch?v=1Da4UmE2f9U" target="_blank"><img src="https://raw.githubusercontent.com/mmadfox/swag2mcp/main/docs/cover.png" alt="Preview"></a><h2 id="your-api-speaks-llm" tabindex="-1">Your API speaks LLM <a class="header-anchor" href="#your-api-speaks-llm" aria-label="Permalink to &quot;Your API speaks LLM&quot;">​</a></h2><p>One line of config turns any OpenAPI/Swagger/Postman file into an MCP server. LLM agents discover, inspect, and invoke your APIs — zero integration code.</p><img src="'+e+'" width="700" alt="swag2mcp architecture"><h2 id="stop-writing-wrappers" tabindex="-1">Stop writing wrappers <a class="header-anchor" href="#stop-writing-wrappers" aria-label="Permalink to &quot;Stop writing wrappers&quot;">​</a></h2><p>Every time you connect a new API to an LLM, you write the same boilerplate: spec parsing, authentication, error handling, rate limiting. swag2mcp does it for you — 19 ready-made MCP tools.</p><h2 id="who-needs-this" tabindex="-1">Who needs this <a class="header-anchor" href="#who-needs-this" aria-label="Permalink to &quot;Who needs this&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Why</th></tr></thead><tbody><tr><td><strong>AI Agent Developer</strong></td><td>Connect any API in 2 minutes, not 2 days</td></tr><tr><td><strong>MCP Engineer</strong></td><td>No handler code — just point to a spec</td></tr><tr><td><strong>Architect</strong></td><td>Single API integration layer for all LLMs in your company</td></tr><tr><td><strong>Data Analyst</strong></td><td>Access APIs via natural language, no coding</td></tr><tr><td><strong>DevOps / SRE</strong></td><td>Monitoring and automation through LLM without extra services</td></tr><tr><td><strong>Integrator</strong></td><td>9 auth methods out of the box — Basic to OAuth2 to HMAC</td></tr><tr><td><strong>QA Engineer</strong></td><td>Mock server for isolated testing without real APIs</td></tr><tr><td><strong>Product Manager</strong></td><td>Rapid AI feature prototypes without backend work</td></tr><tr><td><strong>and many others</strong></td><td></td></tr></tbody></table><hr><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>Licensed under the <strong>GNU Affero General Public License v3.0</strong> (AGPL v3).</p><p>See <a href="https://github.com/mmadfox/swag2mcp/blob/main/LICENSE" target="_blank" rel="noreferrer">LICENSE</a> for the full license text.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SPDX-License-Identifier: AGPL-3.0-only</span></span></code></pre></div>',16)])])}const w=a(s,[["render",i]]);export{u as __pageData,w as default};
